#!/usr/bin/env node
/**
 * CLI entry — arg parsing and command dispatch (the package `bin`).
 *
 * Commands: default `run`, plus `init`, `doctor`, and `fix`. The command is the
 * first non-flag token; everything after it is parsed against that command's
 * options. The module is import-safe: it only executes when invoked directly,
 * so tests can import {@link runCli} without triggering a process exit.
 *
 * Exit codes: 0 pass, 1 check/verification failure, 2 orchestrator/usage error.
 */

import { parseArgs } from 'node:util';
import { pathToFileURL } from 'node:url';

import { runDoctor } from './doctor.js';
import type { InitOptions, Shape } from './init.js';
import { runInit } from './init.js';
import type { Out, RunFlags } from './orchestrator.js';
import { runChecks, runFix } from './orchestrator.js';

/** Injected process surface, so {@link runCli} is testable. */
export type CliDeps = { cwd: string; stdout: Out; stderr: Out };

const RUN_OPTIONS = {
  bail: { type: 'boolean', default: false },
  json: { type: 'boolean', default: false },
  only: { type: 'string' },
  skip: { type: 'string' },
  include: { type: 'string' },
  all: { type: 'boolean', default: false },
  changed: { type: 'boolean', default: false },
} as const;

const INIT_OPTIONS = {
  shape: { type: 'string' },
  name: { type: 'string' },
  scope: { type: 'string' },
  license: { type: 'string' },
  author: { type: 'string' },
  'dry-run': { type: 'boolean', default: false },
  add: { type: 'string' },
} as const;

function errorMessage(err: unknown): string {
  return err instanceof Error ? err.message : String(err);
}

function parseList(value: string | undefined): string[] | null {
  if (!value) return null;
  return value.split(',').map((s) => s.trim()).filter(Boolean);
}

/** The command is the first non-flag token; the rest are its arguments. */
function detectCommand(argv: string[]): { command: string; rest: string[] } {
  const first = argv[0];
  if (first !== undefined && !first.startsWith('-')) {
    return { command: first, rest: argv.slice(1) };
  }
  return { command: 'run', rest: argv };
}

/** Parse argv into a command name and the run flags. */
export function parseCliArgs(argv: string[]): { command: string; flags: RunFlags } {
  const { command, rest } = detectCommand(argv);
  const { values } = parseArgs({ args: rest, allowPositionals: true, options: RUN_OPTIONS });
  const flags: RunFlags = {
    bail: values.bail,
    json: values.json,
    all: values.all,
    changed: values.changed,
    only: parseList(values.only),
    skip: parseList(values.skip),
    include: parseList(values.include),
  };
  return { command, flags };
}

function asShape(value: string | undefined): Shape | undefined {
  if (value === undefined) return undefined;
  if (value === 'flat' || value === 'monorepo' || value === 'hybrid') return value;
  throw new Error(`invalid --shape '${value}' (expected flat | monorepo | hybrid)`);
}

/** Parse `init` arguments into init options. */
export function parseInitArgs(argv: string[]): Partial<InitOptions> {
  const { rest } = detectCommand(argv);
  const { values } = parseArgs({ args: rest, allowPositionals: true, options: INIT_OPTIONS });
  const opts: Partial<InitOptions> = {};
  const shape = asShape(values.shape);
  if (shape) opts.shape = shape;
  if (values.name) opts.name = values.name;
  if (values.scope) opts.scope = values.scope;
  if (values.license) opts.license = values.license;
  if (values.author) opts.author = values.author;
  if (values['dry-run']) opts.dryRun = true;
  const add = parseList(values.add);
  if (add) opts.add = add;
  return opts;
}

async function dispatchRun(argv: string[], deps: CliDeps): Promise<number> {
  const { flags } = parseCliArgs(argv);
  const result = await runChecks({ ...flags, cwd: deps.cwd, stdout: deps.stdout, stderr: deps.stderr });
  return result.exitCode;
}

async function dispatchInit(argv: string[], deps: CliDeps): Promise<number> {
  const result = await runInit({ ...parseInitArgs(argv), cwd: deps.cwd, stdout: deps.stdout });
  return result.exitCode;
}

async function dispatchDoctor(argv: string[], deps: CliDeps): Promise<number> {
  const { flags } = parseCliArgs(argv);
  const result = await runDoctor({ json: flags.json ?? false, cwd: deps.cwd, stdout: deps.stdout });
  return result.exitCode;
}

async function dispatchFix(argv: string[], deps: CliDeps): Promise<number> {
  const { flags } = parseCliArgs(argv);
  const result = await runFix({ ...flags, cwd: deps.cwd, stderr: deps.stderr });
  return result.exitCode;
}

/** Dispatch a CLI invocation; returns the process exit code. */
export async function runCli(argv: string[], deps: CliDeps): Promise<number> {
  const { command } = detectCommand(argv);
  const dispatch: Record<string, (a: string[], d: CliDeps) => Promise<number>> = {
    run: dispatchRun,
    init: dispatchInit,
    doctor: dispatchDoctor,
    fix: dispatchFix,
  };
  const handler = dispatch[command];
  if (!handler) {
    deps.stderr.write(`checkride: unknown command '${command}'.\n`);
    return 2;
  }
  try {
    return await handler(argv, deps);
  } catch (err) {
    deps.stderr.write(`checkride: ${errorMessage(err)}\n`);
    return 2;
  }
}

const invokedDirectly =
  process.argv[1] !== undefined && import.meta.url === pathToFileURL(process.argv[1]).href;

if (invokedDirectly) {
  const code = await runCli(process.argv.slice(2), {
    cwd: process.cwd(),
    stdout: process.stdout,
    stderr: process.stderr,
  });
  process.exit(code);
}

src/config.ts.source:
/**
 * Configuration: load `checkride.config.json`, detect installed tools, and
 * resolve each slot to an adapter (or a skip reason).
 *
 * Resolution rule per slot (see plan §4):
 *   1. config entry wins  — string picks an adapter; `false` disables the slot;
 *      `{ use, ...overrides }` picks an adapter with overrides; `{ command, args }`
 *      is a custom check needing no adapter.
 *   2. otherwise detection — the first registry adapter for the slot whose
 *      `detect` files exist (or whose `detect` is empty, i.e. always available).
 *   3. otherwise the slot is skipped (skipped ≠ failed).
 */

import { existsSync, readFileSync } from 'node:fs';
import { join } from 'node:path';

import type { Adapter, Slot } from './adapters.js';

/** A custom check: a bare command, no adapter required. */
export type CustomCheck = {
  command: string;
  args?: string[];
  description?: string;
  outputFile?: string | null;
  changedArgs?: string[];
  fixArgs?: string[];
  name?: string;
};

/** Pick an adapter by name, with optional field overrides. */
export type UseConfig = {
  use: string;
  command?: string;
  args?: string[];
  description?: string;
  outputFile?: string | null;
  changedArgs?: string[];
  fixArgs?: string[];
};

/** Per-slot config: adapter name, `false` to disable, an override, or a custom check. */
export type SlotConfig = string | false | UseConfig | CustomCheck;

/** Shape of `checkride.config.json`. */
export type CheckrideConfig = {
  checks?: Record<string, SlotConfig>;
};

/** A slot resolved to a concrete adapter, or marked skipped with a reason. */
export type ResolvedCheck = {
  slot: string;
  optIn: boolean;
  adapter: Adapter | null;
  skip: string | null;
};

const CONFIG_FILE = 'checkride.config.json';

/** Read and parse `checkride.config.json` from `cwd`, or `null` when absent. */
export function loadConfig(cwd: string): CheckrideConfig | null {
  const path = join(cwd, CONFIG_FILE);
  if (!existsSync(path)) return null;
  const text = readFileSync(path, 'utf8');
  const config: CheckrideConfig = JSON.parse(text);
  return config;
}

function byName(name: string, adapters: readonly Adapter[]): Adapter | null {
  return adapters.find((a) => a.name === name) ?? null;
}

/** First adapter for `slot` whose detect files are present (empty detect = always). */
function detectAdapter(
  slot: string,
  adapters: readonly Adapter[],
  fileExists: (file: string) => boolean,
): Adapter | null {
  for (const a of adapters) {
    if (a.slot !== slot) continue;
    if (a.detect.length === 0 || a.detect.some((f) => fileExists(f))) return a;
  }
  return null;
}

function applyOverrides(base: Adapter, o: UseConfig): Adapter {
  return {
    ...base,
    ...(o.command !== undefined ? { command: o.command } : {}),
    ...(o.args !== undefined ? { args: o.args } : {}),
    ...(o.outputFile !== undefined ? { outputFile: o.outputFile } : {}),
    ...(o.changedArgs !== undefined ? { changedArgs: o.changedArgs } : {}),
    ...(o.fixArgs !== undefined ? { fixArgs: o.fixArgs } : {}),
    ...(o.description !== undefined ? { description: o.description } : {}),
  };
}

function customAdapter(slot: string, c: CustomCheck): Adapter {
  return {
    name: c.name ?? `custom:${slot}`,
    slot,
    description: c.description ?? `Custom ${slot} check`,
    detect: [],
    command: c.command,
    args: c.args ?? [],
    outputFile: c.outputFile ?? null,
    ...(c.changedArgs !== undefined ? { changedArgs: c.changedArgs } : {}),
    ...(c.fixArgs !== undefined ? { fixArgs: c.fixArgs } : {}),
    devDeps: {},
  };
}

function active(slot: Slot, adapter: Adapter): ResolvedCheck {
  return { slot: slot.name, optIn: slot.optIn ?? false, adapter, skip: null };
}

function skipped(slot: Slot, reason: string): ResolvedCheck {
  return { slot: slot.name, optIn: slot.optIn ?? false, adapter: null, skip: reason };
}

function resolveOne(
  slot: Slot,
  entry: SlotConfig | undefined,
  adapters: readonly Adapter[],
  fileExists: (file: string) => boolean,
): ResolvedCheck {
  if (entry === false) {
    return skipped(slot, 'disabled in checkride.config.json');
  }
  if (typeof entry === 'string') {
    const adapter = byName(entry, adapters);
    return adapter
      ? active(slot, adapter)
      : skipped(slot, `configured adapter '${entry}' is not in the registry`);
  }
  if (entry && typeof entry === 'object') {
    if ('use' in entry) {
      const base = byName(entry.use, adapters);
      return base
        ? active(slot, applyOverrides(base, entry))
        : skipped(slot, `configured adapter '${entry.use}' is not in the registry`);
    }
    if ('command' in entry) {
      return active(slot, customAdapter(slot.name, entry));
    }
  }
  const detected = detectAdapter(slot.name, adapters, fileExists);
  return detected ? active(slot, detected) : skipped(slot, 'no tool detected for slot');
}

/**
 * Resolve every catalogue slot (in order) to an adapter or a skip reason, then
 * append any config-only custom checks (an object with a `command`, keyed by a
 * name not in the catalogue — e.g. a project's `"licenses"` check).
 */
export function resolveChecks(input: {
  slots: readonly Slot[];
  adapters: readonly Adapter[];
  config: CheckrideConfig | null;
  cwd?: string;
  fileExists?: (file: string) => boolean;
}): ResolvedCheck[] {
  const cwd = input.cwd ?? process.cwd();
  const fileExists = input.fileExists ?? ((file: string) => existsSync(join(cwd, file)));
  const checks = input.config?.checks ?? {};
  const catalogue = input.slots.map((slot) =>
    resolveOne(slot, checks[slot.name], input.adapters, fileExists),
  );

  const catalogueNames = new Set(input.slots.map((s) => s.name));
  const extras: ResolvedCheck[] = [];
  for (const [name, entry] of Object.entries(checks)) {
    if (catalogueNames.has(name)) continue;
    if (entry && typeof entry === 'object' && !('use' in entry) && 'command' in entry) {
      extras.push(active({ name }, customAdapter(name, entry)));
    }
  }

  return [...catalogue, ...extras];
}

src/doctor.ts.source:
/**
 * `checkride doctor` — read-only environment + tooling verification.
 *
 * Ported from the reference `scaffold-check.mjs`. Verifies node/pnpm/git are
 * present at the required versions, the project has been installed, each
 * *active* slot's tool resolves in `node_modules/.bin`, and `.check/` is
 * writable. Renders a human table (or `--json`) and exits 0 when everything
 * required is present, 1 otherwise.
 *
 * Every environment touch (PATH, fs, package.json) goes through an injectable
 * {@link DoctorEnv}, so the logic is unit-testable without a real toolchain.
 */

import { execFile } from 'node:child_process';
import { existsSync, readFileSync } from 'node:fs';
import { mkdir, rm, writeFile } from 'node:fs/promises';
import { arch as osArch, platform as osPlatform } from 'node:os';
import { join } from 'node:path';
import { promisify } from 'node:util';

import type { Adapter, Slot } from './adapters.js';
import { ADAPTERS, SLOTS } from './adapters.js';
import type { CheckrideConfig } from './config.js';
import { loadConfig, resolveChecks } from './config.js';
import type { Out } from './orchestrator.js';
import { selectChecks } from './orchestrator.js';

export type DoctorStatus = 'ok' | 'outdated' | 'missing' | 'unknown';

export type DoctorCheck = {
  name: string;
  category: 'env' | 'install' | 'tool' | 'workspace';
  required: boolean;
  status: DoctorStatus;
  found: string | null;
  expected: string | null;
  hint: string | null;
};

export type DoctorReport = {
  ok: boolean;
  platform: { os: string; arch: string };
  checks: DoctorCheck[];
};

export type DoctorResult = { ok: boolean; report: DoctorReport; exitCode: number };

/** Every environment touch, injectable for tests. */
export type DoctorEnv = {
  which: (cmd: string) => Promise<string | null>;
  version: (cmd: string, args: string[]) => Promise<string | null>;
  exists: (path: string) => boolean;
  canWrite: (dir: string) => Promise<boolean>;
  readEngines: (cwd: string) => { node?: string; pnpm?: string };
  platform: () => { os: string; arch: string };
};

export type DoctorOptions = {
  cwd?: string;
  json?: boolean;
  stdout?: Out;
  slots?: readonly Slot[];
  adapters?: readonly Adapter[];
  config?: CheckrideConfig | null;
  env?: DoctorEnv;
};

type Semver = { major: number; minor: number; patch: number; raw: string };

const execFileP = promisify(execFile);

const INSTALL_HINTS: Record<string, string> = {
  node: 'Install Node >=24: https://nodejs.org/ or `nvm install 24 && nvm use 24`',
  pnpm: 'Install pnpm >=9: `corepack enable && corepack prepare pnpm@latest --activate`',
  git: 'Install git: https://git-scm.com/downloads',
  install: 'Run `pnpm install` from the repo root.',
};

async function whichReal(cmd: string): Promise<string | null> {
  try {
    const { stdout } = await execFileP(process.platform === 'win32' ? 'where' : 'which', [cmd]);
    const first = stdout.split('\n').find((l) => l.trim());
    return first ? first.trim() : null;
  } catch {
    return null;
  }
}

async function versionReal(cmd: string, args: string[]): Promise<string | null> {
  try {
    const { stdout } = await execFileP(cmd, args, { timeout: 5000 });
    return stdout.trim();
  } catch {
    return null;
  }
}

async function canWriteReal(dir: string): Promise<boolean> {
  try {
    await mkdir(dir, { recursive: true });
    const probe = join(dir, `.write-probe-${process.pid}`);
    await writeFile(probe, '');
    await rm(probe, { force: true });
    return true;
  } catch {
    return false;
  }
}

function readEnginesReal(cwd: string): { node?: string; pnpm?: string } {
  try {
    const raw = readFileSync(join(cwd, 'package.json'), 'utf8');
    const pkg: { engines?: { node?: string; pnpm?: string } } = JSON.parse(raw);
    return pkg.engines ?? {};
  } catch {
    return {};
  }
}

const realEnv: DoctorEnv = {
  which: whichReal,
  version: versionReal,
  exists: existsSync,
  canWrite: canWriteReal,
  readEngines: readEnginesReal,
  platform: () => ({ os: osPlatform(), arch: osArch() }),
};

function parseSemver(text: string | null | undefined): Semver | null {
  if (!text) return null;
  const m = /(\d+)\.(\d+)\.(\d+)/.exec(text);
  if (!m) return null;
  return { major: Number(m[1]), minor: Number(m[2]), patch: Number(m[3]), raw: m[0] };
}

function compareSemver(a: Semver, b: Semver): number {
  if (a.major !== b.major) return a.major - b.major;
  if (a.minor !== b.minor) return a.minor - b.minor;
  return a.patch - b.patch;
}

function formatExpected(min: Semver): string {
  return `>=${min.major}.${min.minor}.${min.patch}`;
}

async function checkVersioned(name: string, cmd: string, min: Semver, env: DoctorEnv): Promise<DoctorCheck> {
  const expected = formatExpected(min);
  const path = await env.which(cmd);
  if (!path) {
    return { name, category: 'env', required: true, status: 'missing', found: null, expected, hint: INSTALL_HINTS[name] ?? `Install \`${cmd}\`.` };
  }
  const found = parseSemver(await env.version(cmd, ['--version']));
  if (!found) {
    return { name, category: 'env', required: true, status: 'unknown', found: null, expected, hint: `Could not parse \`${cmd} --version\` output.` };
  }
  if (compareSemver(found, min) < 0) {
    return { name, category: 'env', required: true, status: 'outdated', found: found.raw, expected, hint: INSTALL_HINTS[name] ?? `Upgrade \`${cmd}\` to ${expected}.` };
  }
  return { name, category: 'env', required: true, status: 'ok', found: found.raw, expected, hint: null };
}

async function checkPresent(name: string, cmd: string, env: DoctorEnv): Promise<DoctorCheck> {
  const path = await env.which(cmd);
  if (!path) {
    return { name, category: 'env', required: true, status: 'missing', found: null, expected: 'present on PATH', hint: INSTALL_HINTS[name] ?? `Install \`${cmd}\`.` };
  }
  const raw = await env.version(cmd, ['--version']);
  return { name, category: 'env', required: true, status: 'ok', found: raw ?? path, expected: 'present on PATH', hint: null };
}

function checkInstall(cwd: string, env: DoctorEnv): DoctorCheck {
  if (!env.exists(join(cwd, 'pnpm-lock.yaml'))) {
    return { name: 'install', category: 'install', required: true, status: 'missing', found: null, expected: 'pnpm-lock.yaml present', hint: INSTALL_HINTS['install'] ?? null };
  }
  if (!env.exists(join(cwd, 'node_modules'))) {
    return { name: 'install', category: 'install', required: true, status: 'missing', found: 'lockfile only', expected: 'node_modules/ populated', hint: INSTALL_HINTS['install'] ?? null };
  }
  return { name: 'install', category: 'install', required: true, status: 'ok', found: 'node_modules + lockfile', expected: null, hint: null };
}

async function checkTool(adapter: Adapter, cwd: string, env: DoctorEnv): Promise<DoctorCheck> {
  const name = `${adapter.name} (${adapter.slot})`;
  if (adapter.builtin) {
    return { name, category: 'tool', required: true, status: 'ok', found: 'built-in', expected: null, hint: null };
  }
  if (adapter.command === 'pnpm' && adapter.args[0] === 'exec') {
    const tool = adapter.args[1];
    if (!tool) {
      return { name, category: 'tool', required: true, status: 'unknown', found: null, expected: null, hint: null };
    }
    const bin = join(cwd, 'node_modules', '.bin', tool);
    return env.exists(bin)
      ? { name, category: 'tool', required: true, status: 'ok', found: bin, expected: `node_modules/.bin/${tool}`, hint: null }
      : { name, category: 'tool', required: true, status: 'missing', found: null, expected: `node_modules/.bin/${tool}`, hint: `Run \`pnpm install\` (or add ${tool}).` };
  }
  const path = await env.which(adapter.command);
  return path
    ? { name, category: 'tool', required: true, status: 'ok', found: path, expected: `${adapter.command} on PATH`, hint: null }
    : { name, category: 'tool', required: true, status: 'missing', found: null, expected: `${adapter.command} on PATH`, hint: `Install \`${adapter.command}\`.` };
}

async function checkWritable(cwd: string, env: DoctorEnv): Promise<DoctorCheck> {
  const dir = join(cwd, '.check');
  const ok = await env.canWrite(dir);
  return ok
    ? { name: '.check', category: 'workspace', required: true, status: 'ok', found: 'writable', expected: 'writable', hint: null }
    : { name: '.check', category: 'workspace', required: true, status: 'missing', found: 'not writable', expected: 'writable', hint: `Ensure ${dir} is writable.` };
}

function statusMark(status: DoctorStatus): string {
  if (status === 'ok') return '✔';
  if (status === 'outdated') return '⚠';
  return '✘';
}

const GROUPS: { key: DoctorCheck['category']; label: string }[] = [
  { key: 'env', label: 'ENVIRONMENT' },
  { key: 'install', label: 'INSTALL' },
  { key: 'tool', label: 'TOOLS' },
  { key: 'workspace', label: 'WORKSPACE' },
];

function renderTable(report: DoctorReport, out: Out): void {
  out.write('\ncheckride doctor\n\n');
  for (const group of GROUPS) {
    const items = report.checks.filter((c) => c.category === group.key);
    if (items.length === 0) continue;
    out.write(`  ${group.label}\n`);
    for (const c of items) {
      const found = c.found ?? '—';
      const expected = c.expected ? `  (${c.expected})` : '';
      out.write(`  ${statusMark(c.status)} ${c.name.padEnd(22)} ${found}${expected}\n`);
      if (c.status !== 'ok' && c.hint) out.write(`      -> ${c.hint}\n`);
    }
  }
  out.write(report.ok ? '\n✔ environment ok\n\n' : '\n✘ environment has problems (see above)\n\n');
}

/** Run the doctor against `cwd`; render and return the report. */
export async function runDoctor(options: DoctorOptions): Promise<DoctorResult> {
  const cwd = options.cwd ?? process.cwd();
  const slots = options.slots ?? SLOTS;
  const adapters = options.adapters ?? ADAPTERS;
  const config = options.config !== undefined ? options.config : loadConfig(cwd);
  const stdout = options.stdout ?? process.stdout;
  const env = options.env ?? realEnv;
  const json = options.json ?? false;

  const engines = env.readEngines(cwd);
  const nodeMin = parseSemver(engines.node) ?? { major: 24, minor: 0, patch: 0, raw: '24.0.0' };
  const pnpmMin = parseSemver(engines.pnpm) ?? { major: 9, minor: 0, patch: 0, raw: '9.0.0' };

  const checks: DoctorCheck[] = [
    await checkVersioned('node', 'node', nodeMin, env),
    await checkVersioned('pnpm', 'pnpm', pnpmMin, env),
    await checkPresent('git', 'git', env),
    checkInstall(cwd, env),
  ];

  // Verify the tools the default run uses (opt-in slots are excluded unless run).
  const resolved = resolveChecks({ slots, adapters, config, cwd });
  const active = selectChecks(resolved, {}).filter((r) => r.adapter && !r.skip);
  for (const r of active) {
    if (r.adapter) checks.push(await checkTool(r.adapter, cwd, env));
  }

  checks.push(await checkWritable(cwd, env));

  const ok = checks.every((c) => !c.required || c.status === 'ok');
  const report: DoctorReport = { ok, platform: env.platform(), checks };

  if (json) {
    stdout.write(`${JSON.stringify(report, null, 2)}\n`);
  } else {
    renderTable(report, stdout);
  }

  return { ok, report, exitCode: ok ? 0 : 1 };
}

src/init.ts.source:
/**
 * `checkride init` — set up a project (new or existing, auto-detected).
 *
 * New-project mode generates a complete, green-out-of-the-box repo for one of
 * three shapes (flat / monorepo / hybrid); the shapes differ only in
 * tsconfig.json, fallow.toml, and pnpm-workspace.yaml. Existing-project mode is
 * additive: it inventories detectable tools, writes only what is missing
 * (checkride.config.json, the AGENTS stanza, the `check` alias) and never
 * touches an existing tool config.
 *
 * Generation, not transformation: every file is written once; the project owns
 * it afterward.
 */

import { existsSync, readFileSync } from 'node:fs';
import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { basename, dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

import type { Adapter, Slot } from './adapters.js';
import { ADAPTERS, SLOTS } from './adapters.js';
import { resolveChecks } from './config.js';
import type { Out } from './orchestrator.js';
import { runChecks } from './orchestrator.js';

export type Shape = 'flat' | 'monorepo' | 'hybrid';

export type InitOptions = {
  cwd?: string;
  shape?: Shape;
  name?: string;
  scope?: string | null;
  license?: string;
  author?: string | null;
  dryRun?: boolean;
  add?: string[] | null;
  checkrideSpec?: string;
  stdout?: Out;
  slots?: readonly Slot[];
  adapters?: readonly Adapter[];
  /** Existing mode: returns the adopted slots whose check currently fails. */
  probeFailures?: (slots: string[], cwd: string) => Promise<string[]>;
};

export type InitResult = {
  mode: 'new' | 'existing';
  shape: Shape | null;
  written: string[];
  skipped: string[];
  disabled: string[];
  exitCode: number;
};

const NULL_OUT: Out = { write: () => true };

/** Run the adopted checks once; a failing (non-skipped) check marks its slot. */
async function defaultProbe(slots: string[], cwd: string): Promise<string[]> {
  if (slots.length === 0) return [];
  const { summary } = await runChecks({ cwd, only: slots, json: true, stdout: NULL_OUT, stderr: NULL_OUT });
  return summary.checks.filter((c) => !c.ok && c.skipped !== true).map((c) => c.name);
}

export type InventoryEntry = { slot: string; status: 'adopted' | 'empty'; adapter: string | null };

const HERE = dirname(fileURLToPath(import.meta.url));
const TEMPLATES_DIR = join(HERE, '..', 'templates');

const STANZA_BEGIN = '<!-- checkride:begin -->';
const STANZA_END = '<!-- checkride:end -->';

// ----------------------------------------------------------------------------
// AGENTS.md stanza (gate: idempotent)
// ----------------------------------------------------------------------------

function escapeRegex(text: string): string {
  return text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

/** The agent-facing contract block, parameterized by the active checks. */
export function buildStanza(activeSlots: readonly string[]): string {
  return [
    '## Checkride: the definition of done',
    '',
    '`pnpm check` is the single source of truth for "done". Exit 0 means the work is',
    'complete; any other exit code means it is not. Never claim a task is finished while',
    '`pnpm check` is red.',
    '',
    'When it fails:',
    '',
    '1. Read `.check/summary.json` to see which check failed.',
    "2. Read that check's raw output (`.check/<slot>.json` or `.check/<slot>.stdout.txt`).",
    '3. Fix the root cause, then re-run.',
    '',
    'Tight feedback loops: `pnpm check --bail`, `pnpm check --only types,lint`, and',
    '`pnpm check --changed`.',
    '',
    '### Module boundaries',
    '',
    'Every first-level directory under `src/` is a module whose only public surface is',
    "its `index.ts`. Import siblings through `'../<sibling>/index.js'`, never their",
    'internals. Named exports only; no classes; `.js` extensions on relative imports.',
    '',
    `Active checks in this repo: ${activeSlots.join(', ')}.`,
  ].join('\n');
}

/**
 * Insert or refresh the checkride stanza in an AGENTS.md body. Idempotent:
 * applying twice yields identical output.
 */
export function applyStanza(content: string, body: string): string {
  const block = `${STANZA_BEGIN}\n\n${body}\n\n${STANZA_END}`;
  const re = new RegExp(`${escapeRegex(STANZA_BEGIN)}[\\s\\S]*?${escapeRegex(STANZA_END)}`);
  if (re.test(content)) {
    return content.replace(re, block);
  }
  if (content.trim().length === 0) {
    return `${block}\n`;
  }
  return `${content.replace(/\s*$/, '')}\n\n${block}\n`;
}

// ----------------------------------------------------------------------------
// Inventory (gate: adoption inventory)
// ----------------------------------------------------------------------------

/** For each default (non-opt-in) slot, report whether a tool config is present. */
export function inventory(input: {
  cwd?: string;
  slots?: readonly Slot[];
  adapters?: readonly Adapter[];
  fileExists?: (file: string) => boolean;
}): InventoryEntry[] {
  const slots = (input.slots ?? SLOTS).filter((s) => !s.optIn);
  const resolved = resolveChecks({
    slots,
    adapters: input.adapters ?? ADAPTERS,
    config: null,
    ...(input.cwd !== undefined ? { cwd: input.cwd } : {}),
    ...(input.fileExists !== undefined ? { fileExists: input.fileExists } : {}),
  });
  return resolved.map((r) => ({
    slot: r.slot,
    status: r.adapter ? 'adopted' : 'empty',
    adapter: r.adapter?.name ?? null,
  }));
}

// ----------------------------------------------------------------------------
// Generation helpers
// ----------------------------------------------------------------------------

function readTemplate(rel: string): string {
  return readFileSync(join(TEMPLATES_DIR, rel), 'utf8');
}

function render(text: string, vars: Record<string, string>): string {
  return text.replace(/\{\{(\w+)\}\}/g, (_m, key: string) => vars[key] ?? '');
}

function constName(name: string): string {
  const id = name.toUpperCase().replace(/[^A-Z0-9]+/g, '_').replace(/^_+|_+$/g, '');
  return id.length > 0 ? id : 'APP';
}

function productVersion(): string {
  try {
    const raw = readFileSync(join(TEMPLATES_DIR, '..', 'package.json'), 'utf8');
    const pkg: { version?: string } = JSON.parse(raw);
    return pkg.version ?? '0.1.0';
  } catch {
    return '0.1.0';
  }
}

function collectDevDeps(
  adapters: readonly Adapter[],
  slots: readonly Slot[],
  checkrideSpec: string,
): Record<string, string> {
  const deps: Record<string, string> = {};
  for (const slot of slots) {
    if (slot.optIn) continue;
    const adapter = adapters.find((a) => a.slot === slot.name);
    if (adapter) Object.assign(deps, adapter.devDeps);
  }
  deps['checkride'] = checkrideSpec;
  const sorted: Record<string, string> = {};
  for (const key of Object.keys(deps).toSorted()) sorted[key] = deps[key] ?? '';
  return sorted;
}

function rootPackageJson(
  fullName: string,
  license: string,
  author: string | null,
  devDeps: Record<string, string>,
  workspace: boolean,
): string {
  const pkg = {
    name: fullName,
    version: '0.1.0',
    description: '',
    license,
    ...(author ? { author } : {}),
    type: 'module',
    ...(workspace ? { private: true } : {}),
    engines: { node: '>=24.0.0', pnpm: '>=9.0.0' },
    scripts: {
      check: 'checkride',
      'check:all': 'checkride --all',
      'check:json': 'checkride --json',
      'check:bail': 'checkride --bail',
      'check:changed': 'checkride --changed',
      'check:fix': 'checkride fix',
      doctor: 'checkride doctor',
      test: 'vitest run',
      'test:watch': 'vitest',
      build: 'tsc --build',
      types: 'tsc --build',
    },
    devDependencies: devDeps,
  };
  return `${JSON.stringify(pkg, null, 2)}\n`;
}

function packageJsonFor(pkgName: string): string {
  const pkg = {
    name: pkgName,
    version: '0.0.0',
    private: true,
    type: 'module',
    exports: { '.': './src/index.ts' },
  };
  return `${JSON.stringify(pkg, null, 2)}\n`;
}

const PACKAGE_TSCONFIG = `${JSON.stringify(
  {
    extends: '../../tsconfig.base.json',
    compilerOptions: { rootDir: './src', outDir: './dist' },
    include: ['src/**/*'],
    exclude: ['dist', 'node_modules'],
  },
  null,
  2,
)}\n`;

function sourceModule(value: string): string {
  const id = constName(value);
  return `export const ${id} = '${value}';\n`;
}

function smokeTest(value: string): string {
  const id = constName(value);
  return [
    "import { expect, test } from 'vitest';",
    '',
    "import { " + id + " } from './index.js';",
    '',
    `test('${value} smoke', () => {`,
    `  expect(${id}).toBe('${value}');`,
    '});',
    '',
  ].join('\n');
}

function readme(name: string): string {
  return [
    `# ${name}`,
    '',
    'A TypeScript project verified by checkride.',
    '',
    '```bash',
    'pnpm check        # run the full pipeline; exit 0 = done',
    '```',
    '',
    'See [AGENTS.md](./AGENTS.md) for the contract agents follow in this repository.',
    '',
  ].join('\n');
}

function claudeMd(): string {
  return [
    '# CLAUDE.md',
    '',
    'Claude Code-specific notes. See [AGENTS.md](./AGENTS.md) for the full contract.',
    '',
  ].join('\n');
}

function agentsMd(activeSlots: readonly string[]): string {
  const intro = ['# AGENTS.md', '', 'Instructions for any coding agent working in this repository.', ''].join('\n');
  return applyStanza(intro, buildStanza(activeSlots));
}

const MIT = (year: number, holder: string): string =>
  [
    'MIT License',
    '',
    `Copyright (c) ${year} ${holder}`,
    '',
    'Permission is hereby granted, free of charge, to any person obtaining a copy',
    'of this software and associated documentation files (the "Software"), to deal',
    'in the Software without restriction, including without limitation the rights',
    'to use, copy, modify, merge, publish, distribute, sublicense, and/or sell',
    'copies of the Software, and to permit persons to whom the Software is',
    'furnished to do so, subject to the following conditions:',
    '',
    'The above copyright notice and this permission notice shall be included in all',
    'copies or substantial portions of the Software.',
    '',
    'THE SOFTWARE IS PROVIDED "AS IS", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR',
    'IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY,',
    'FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE',
    'AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER',
    'LIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM,',
    'OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE',
    'SOFTWARE.',
    '',
  ].join('\n');

function licenseText(license: string, holder: string): string {
  const year = new Date().getFullYear();
  if (license === 'MIT') return MIT(year, holder);
  return `${license} License\n\nCopyright (c) ${year} ${holder}\n`;
}

function cspellWithName(name: string, scope: string | null): string {
  const base: { words?: string[] } & Record<string, unknown> = JSON.parse(readTemplate('shared/cspell.json'));
  const words = new Set(base.words ?? []);
  for (const token of `${name} ${scope ?? ''}`.split(/[^A-Za-z0-9]+/)) {
    if (token.length > 1) words.add(token);
  }
  base.words = [...words].toSorted();
  return `${JSON.stringify(base, null, 2)}\n`;
}

// ----------------------------------------------------------------------------
// Writers
// ----------------------------------------------------------------------------

type Writer = {
  cwd: string;
  dryRun: boolean;
  written: string[];
};

async function put(w: Writer, relPath: string, content: string): Promise<void> {
  w.written.push(relPath);
  if (w.dryRun) return;
  const target = join(w.cwd, relPath);
  await mkdir(dirname(target), { recursive: true });
  await writeFile(target, content);
}

async function writeSharedStatic(w: Writer): Promise<void> {
  const map: [string, string][] = [
    ['shared/tsconfig.base.json', 'tsconfig.base.json'],
    ['shared/oxlintrc.json', '.oxlintrc.json'],
    ['shared/markdownlint-cli2.jsonc', '.markdownlint-cli2.jsonc'],
    ['shared/sgconfig.yml', 'sgconfig.yml'],
    ['shared/vitest.config.ts.template', 'vitest.config.ts'],
    ['shared/gitignore', '.gitignore'],
    ['shared/npmrc', '.npmrc'],
  ];
  for (const [from, to] of map) await put(w, to, readTemplate(from));
  for (const rule of ['no-class.yml', 'no-default-export.yml', 'no-deep-sibling-import.yml', 'require-js-extension.yml']) {
    await put(w, join('rules', rule), readTemplate(join('shared', 'rules', rule)));
  }
}

async function writePackage(w: Writer, dir: string, pkgName: string, value: string): Promise<void> {
  await put(w, join(dir, 'package.json'), packageJsonFor(pkgName));
  await put(w, join(dir, 'tsconfig.json'), PACKAGE_TSCONFIG);
  await put(w, join(dir, 'src', 'index.ts'), sourceModule(value));
  await put(w, join(dir, 'src', 'index.test.ts'), smokeTest(value));
}

// ----------------------------------------------------------------------------
// New-project mode
// ----------------------------------------------------------------------------

const DEFAULT_ACTIVE_SLOTS = ['types', 'lint', 'struct', 'dead', 'test', 'docs', 'links', 'spell'];

async function initNew(options: InitOptions, cwd: string): Promise<InitResult> {
  const shape: Shape = options.shape ?? 'flat';
  const name = options.name ?? (basename(cwd) || 'app');
  const scope = options.scope ?? null;
  const license = options.license ?? 'MIT';
  const author = options.author ?? null;
  const fullName = scope ? `${scope}/${name}` : name;
  const adapters = options.adapters ?? ADAPTERS;
  const slots = options.slots ?? SLOTS;
  const checkrideSpec = options.checkrideSpec ?? `^${productVersion()}`;

  const w: Writer = { cwd, dryRun: options.dryRun ?? false, written: [] };

  await writeSharedStatic(w);
  await put(w, 'tsconfig.json', render(readTemplate(join(shape, 'tsconfig.json')), { name }));
  await put(w, 'fallow.toml', render(readTemplate(join(shape, 'fallow.toml')), { name }));
  await put(w, 'pnpm-workspace.yaml', render(readTemplate(join(shape, 'pnpm-workspace.yaml')), { name }));

  await put(w, 'cspell.json', cspellWithName(name, scope));
  await put(w, 'package.json', rootPackageJson(fullName, license, author, collectDevDeps(adapters, slots, checkrideSpec), shape !== 'flat'));
  await put(w, 'LICENSE', licenseText(license, author ?? fullName));
  await put(w, 'README.md', readme(name));
  await put(w, 'AGENTS.md', agentsMd(DEFAULT_ACTIVE_SLOTS));
  await put(w, 'CLAUDE.md', claudeMd());

  if (shape === 'flat') {
    await put(w, join('src', 'index.ts'), sourceModule(name));
    await put(w, join('src', 'index.test.ts'), smokeTest(name));
  } else if (shape === 'monorepo') {
    await writePackage(w, join('libs', 'core'), scope ? `${scope}/core` : 'core', 'core');
    await writePackage(w, join('apps', name), fullName, name);
  } else {
    await put(w, join('src', 'index.ts'), sourceModule(name));
    await put(w, join('src', 'index.test.ts'), smokeTest(name));
    await writePackage(w, join('packages', 'core'), scope ? `${scope}/core` : 'core', 'core');
  }

  if (options.stdout) {
    options.stdout.write(`checkride init: generated a ${shape} project (${w.written.length} files)${w.dryRun ? ' [dry run]' : ''}.\n`);
  }
  return { mode: 'new', shape, written: w.written, skipped: [], disabled: [], exitCode: 0 };
}

// ----------------------------------------------------------------------------
// Existing-project mode
// ----------------------------------------------------------------------------

async function readIfExists(path: string): Promise<string | null> {
  try {
    return await readFile(path, 'utf8');
  } catch {
    return null;
  }
}

async function initExisting(options: InitOptions, cwd: string): Promise<InitResult> {
  const adapters = options.adapters ?? ADAPTERS;
  const slots = options.slots ?? SLOTS;
  const w: Writer = { cwd, dryRun: options.dryRun ?? false, written: [] };
  const skipped: string[] = [];

  const items = inventory({ cwd, slots, adapters });
  const adopted = items.filter((i) => i.status === 'adopted');

  // Step 3: run each adopted check once; failing slots are recorded as `false`
  // (disabled) so the first `pnpm check` is green-ish — re-enable as you fix.
  const probe = options.probeFailures ?? defaultProbe;
  const failing = new Set(await probe(adopted.map((i) => i.slot), cwd));
  const disabled = adopted.filter((i) => failing.has(i.slot)).map((i) => i.slot);

  // checkride.config.json reflecting adopted tools (and disabled failures). Never
  // overwrite an existing one.
  const configPath = join(cwd, 'checkride.config.json');
  if (!existsSync(configPath)) {
    const checks: Record<string, string | false> = {};
    for (const i of adopted) {
      if (failing.has(i.slot)) checks[i.slot] = false;
      else if (i.adapter) checks[i.slot] = i.adapter;
    }
    await put(w, 'checkride.config.json', `${JSON.stringify({ checks }, null, 2)}\n`);
  } else {
    skipped.push('checkride.config.json (exists)');
  }

  // .gitignore: ensure .check/ is ignored (append, never clobber).
  const gitignorePath = join(cwd, '.gitignore');
  const gi = await readIfExists(gitignorePath);
  if (gi === null) {
    await put(w, '.gitignore', '.check/\n');
  } else if (!/^\.check\/?\s*$/m.test(gi)) {
    if (!w.dryRun) await writeFile(gitignorePath, `${gi.replace(/\s*$/, '')}\n.check/\n`);
    w.written.push('.gitignore (appended .check/)');
  } else {
    skipped.push('.gitignore (.check/ already ignored)');
  }

  // AGENTS.md stanza (create or refresh, idempotent).
  const agentsPath = join(cwd, 'AGENTS.md');
  const existing = await readIfExists(agentsPath);
  const stanza = buildStanza(adopted.map((i) => i.slot));
  const nextAgents = applyStanza(existing ?? '', stanza);
  if (nextAgents !== existing) {
    if (!w.dryRun) await writeFile(agentsPath, nextAgents);
    w.written.push(existing === null ? 'AGENTS.md' : 'AGENTS.md (refreshed stanza)');
  } else {
    skipped.push('AGENTS.md (stanza unchanged)');
  }

  // CLAUDE.md pointer if absent.
  const claudePath = join(cwd, 'CLAUDE.md');
  if (!existsSync(claudePath)) {
    await put(w, 'CLAUDE.md', claudeMd());
  } else {
    skipped.push('CLAUDE.md (exists)');
  }

  if (options.stdout) {
    options.stdout.write(
      `checkride init: adopted ${adopted.length} slot(s); wrote ${w.written.length} file(s)${w.dryRun ? ' [dry run]' : ''}.\n`,
    );
    if (disabled.length > 0) {
      options.stdout.write(`  disabled failing slots (enable as you fix): ${disabled.join(', ')}\n`);
    }
  }
  return { mode: 'existing', shape: null, written: w.written, skipped, disabled, exitCode: 0 };
}

// ----------------------------------------------------------------------------
// Entry
// ----------------------------------------------------------------------------

/** Detect new vs existing by the presence of a package.json. */
export function detectMode(cwd: string): 'new' | 'existing' {
  return existsSync(join(cwd, 'package.json')) ? 'existing' : 'new';
}

/** Run `checkride init` against `cwd`. */
export async function runInit(options: InitOptions): Promise<InitResult> {
  const cwd = options.cwd ?? process.cwd();
  return detectMode(cwd) === 'existing' ? initExisting(options, cwd) : initNew(options, cwd);
}

